  'Icons come from': 'Los iconos provienen de',
  'Same axes as the Figma variant set the plugin generates.': 'Los mismos ejes que el conjunto de variantes de Figma que genera el plugin.',
  'has {count} option —': 'tiene {count} opción:',
  'has {count} options —': 'tiene {count} opciones:',
